glsl:
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(hash(i),hash(i+vec2(1.0,0.0)),f.x),mix(hash(i+vec2(0.0,1.0)),hash(i+vec2(1.0,1.0)),f.x),f.y);}
float sdRoundedRect(vec2 p,vec2 sz,float r){vec2 d=abs(p)-sz+vec2(r);return min(max(d.x,d.y),0.0)+length(max(d,0.0))-r;}
float sdCapsule(vec2 p,vec2 a,vec2 b,float r){vec2 pa=p-a,ba=b-a;float h=clamp(dot(pa,ba)/dot(ba,ba),0.0,1.0);return length(pa-ba*h)-r;}
float sdEllipse(vec2 p,vec2 r){vec2 k=abs(p);if(k.x>k.y){k=k.yx;r=r.yx;}float l=length(k/r);if(l>1.0)return length(k-r);return (length(k)-length(r))*sign(l-1.0);}
float opSmoothU(float d1,float d2,float k){float h=clamp(0.5+0.5*(d2-d1)/k,0.0,1.0);return mix(d2,d1,h)-k*h*(1.0-h);}

vec4 hafizePortrait(vec2 p){
    float idleW=1.0-uListen-uThink-uSpeak;
    float t=uTime;
    float fl=uFlow;
    float px=uPx*1.5;

    // --- State Parameters ---
    // Base Scale: Figure height ~1.6 (80% of height 2.0)
    float baseScale=1.15;
    float spineH=mix(0.85,0.65,uThink)*baseScale;
    float spineW=mix(0.12,0.18,uLight)*baseScale;
    float branchLen=mix(0.95,1.2,uListen)*baseScale;
    float branchWBase=mix(0.10,0.14,uLight)*baseScale;
    float branchWTip=mix(0.03,0.05,uLight)*baseScale;
    float leafScl=mix(0.12,0.16,uLight)*baseScale;

    float breath=1.0+0.02*sin(t*0.9)*idleW;
    float listenSway=sin(t*0.7)*0.08*uListen;
    float thinkPulse=1.0+0.03*sin(t*3.0)*uThink;
    float speakHit=0.0;
    if(uSpeak>0.0){speakHit=uVoice*0.18;} // uVoice is syllable envelope

    float glyphScale=baseScale*breath*thinkPulse*(1.0+speakHit);
    glyphScale+=listenSway*0.1; // subtle horizontal breathing

    // Brush Noise Params
    float brushFreq=5.0;
    float brushAmp=0.012*(1.0+uListen*0.8+uSpeak*0.5);

    // --- Glyph SDF Construction (Local Space) ---
    vec2 gp=p/glyphScale; // Scale coordinate system up
    gp.y+=sin(t*12.0)*0.003*idleW; // Idle micro tremor

    float g=100.0;
    float kBlend=0.04*glyphScale; // Smooth union radius

    // 1. Spine (Central Rounded Rect)
    vec2 spineC=vec2(0.0,0.0);
    vec2 spineSz=vec2(spineW,spineH*0.5);
    float ds=sdRoundedRect(gp-spineC,spineSz,spineW*0.5);
    g=ds;

    // 2. Branches (4 Thick Capsules)
    float yL0=-spineH*0.3;
    float yL1=-spineH*0.55;
    float yL2=-spineH*0.95;
    float xTip=branchLen;

    // Lower Left
    vec2 ll0=vec2(-spineW*0.5,yL0);
    vec2 ll2=vec2(-xTip,yL2);
    float dl=sdCapsule(gp,ll0,ll2,mix(branchWBase,branchWTip,0.5)); // Approx taper via avg radius
    g=opSmoothU(g,dl,kBlend);

    // Lower Right
    vec2 rl0=vec2(spineW*0.5,yL0);
    vec2 rl2=vec2(xTip,yL2);
    float dr=sdCapsule(gp,rl0,rl2,mix(branchWBase,branchWTip,0.5));
    g=opSmoothU(g,dr,kBlend);

    // Upper Left
    float yU0=spineH*0.3;
    float yU2=spineH*0.95;
    vec2 lu0=vec2(-spineW*0.5,yU0);
    vec2 lu2=vec2(-xTip,yU2);
    float dul=sdCapsule(gp,lu0,lu2,mix(branchWBase,branchWTip,0.5));
    g=opSmoothU(g,dul,kBlend);

    // Upper Right
    vec2 ru0=vec2(spineW*0.5,yU0);
    vec2 ru2=vec2(xTip,yU2);
    float dur=sdCapsule(gp,ru0,ru2,mix(branchWBase,branchWTip,0.5));
    g=opSmoothU(g,dur,kBlend);

    // 3. Center Leaf (Ellipse)
    float dleaf=sdEllipse(gp,vec2(leafScl,leafScl*1.8));
    g=opSmoothU(g,dleaf,kBlend*0.5);

    // 4. Thinking Internal Lines (Deterministic Noise Lines)
    if(uThink>0.0){
        for(int i=0;i<6;i++){
            float id=float(i);
            float ang=id*1.047+sin(t*0.5+id)*0.3; // 60 deg steps + wobble
            float len=spineH*0.4*(0.5+0.5*noise(vec2(id,t*0.2)));
            vec2 a=vec2(0.0);
            vec2 b=vec2(sin(ang),cos(ang))*len;
            float dn=sdCapsule(gp,a,b,0.008*glyphScale);
            g=opSmoothU(g,dn,0.01);
        }
    }

    // --- Brush Noise Displacement (Applied to final SDF) ---
    float brushDisp=noise(gp*brushFreq+fl*0.05)*brushAmp;
    g+=brushDisp;

    // --- Aura SDF ---
    float auraRadX=mix(1.3,1.6,uListen)*mix(1.0,0.65,uThink)*glyphScale;
    float auraRadY=mix(1.5,1.9,uListen)*mix(1.0,0.6,uThink)*glyphScale;
    float da=sdEllipse(p,vec2(auraRadX,auraRadY));

    // --- Masks & AA ---
    float glyphMask=smoothstep(-px,px,-g);
    float auraMask=smoothstep(-px*4.0,px*4.0,-da);

    if(glyphMask<0.001 && auraMask<0.001) return vec4(0.0);

    // --- Colors ---
    vec3 colDarkGlyph=vec3(0.96,0.94,0.90); // #f5efe6
    vec3 colDarkGlow=vec3(0.78,0.66,0.43);  // #c8a96e
    vec3 colDarkGlowBright=vec3(0.91,0.83,0.63); // #e8d4a0
    vec3 colLightGlyph=vec3(0.05,0.06,0.08); // #0d0f14
    vec3 colLightGlow=vec3(0.10,0.11,0.15);  // #1a1d26

    vec3 glyphCol=mix(colDarkGlyph,colLightGlyph,uLight);
    vec3 glowCol=mix(colDarkGlow,colLightGlow,uLight);
    vec3 glowColBright=mix(colDarkGlowBright,colLightGlow,uLight);

    // State Color Modulation
    float brightness=1.0;
    vec3 auraCol=glowCol;
    float auraOp=0.0;

    if(uLight<0.5){ // Dark Theme
        brightness=mix(1.0,1.4,uListen)*mix(1.0,1.1,uThink);
        glyphCol*=brightness;

        // Aura Logic
        float idleA=0.04, listenA=0.10, thinkA=0.06, speakA=0.18;
        vec3 idleC=colDarkGlow;
        vec3 listenC=colDarkGlowBright;
        vec3 thinkC=vec3(0.15,0.12,0.08); // Dark warm
        vec3 speakC=vec3(1.0,0.95,0.85);

        auraCol=mix(idleC,listenC,uListen);
        auraCol=mix(auraCol,thinkC,uThink);
        auraCol=mix(auraCol,speakC,uSpeak);
        auraOp=mix(idleA,listenA,uListen);
        auraOp=mix(auraOp,thinkA,uThink);
        auraOp=mix(auraOp,speakA,uSpeak);
        auraOp*=auraMask;
    }else{ // Light Theme
        brightness=mix(1.0,0.8,uListen)*mix(1.0,0.7,uThink); // Darker when active
        glyphCol*=brightness;

        float idleA=0.02, listenA=0.06, thinkA=0.05, speakA=0.12;
        vec3 idleC=colLightGlow;
        vec3 listenC=vec3(0.05,0.06,0.08);
        vec3 thinkC=vec3(0.02,0.02,0.03);
        vec3 speakC=vec3(0.0);

        auraCol=mix(idleC,listenC,uListen);
        auraCol=mix(auraCol,thinkC,uThink);
        auraCol=mix(auraCol,speakC,uSpeak);
        auraOp=mix(idleA,listenA,uListen);
        auraOp=mix(auraOp,thinkA,uThink);
        auraOp=mix(auraOp,speakA,uSpeak);
        auraOp*=auraMask;
    }

    // Speak Flash Override
    if(uSpeak>0.0){
        float flash=uVoice;
        glyphCol=mix(glyphCol,vec3(1.0,0.98,0.92),flash);
        if(uLight<0.5) glowCol=mix(glowCol,vec3(1.0),flash);
    }

    // --- Composition ---
    vec3 col=vec3(0.0);
    float alpha=0.0;

    // Aura (Back)
    col+=auraCol*auraOp*exp(-da*1.5);
    alpha+=auraOp;

    // Glyph Body
    float edgeGlow=exp(-abs(g)*15.0)*glyphMask;
    col+=glyphCol*glyphMask;
    col+=glowCol*edgeGlow*mix(1.5,0.5,uLight)*(1.0+uListen*0.5);
    alpha=max(alpha, glyphMask+edgeGlow*0.3);

    // Tone Map
    col=1.0-exp(-col*1.8);

    return vec4(col,clamp(alpha,0.0,1.0));
}
